	public void LeaveUnion() {
        sessionManager.Clear();
        if (unionFrontController != null)
            unionFrontController.TalkEnd();

        Fader.FadeOut();
        Sequencer.Start(Leave());

        IEnumerator Leave()
        {
            while (NetworkManager.IsConnect || !canLeave)
                yield return null;

            if (UnionWork.GetIsYmenu())
            {
                Vector2Int gridPos = UnionWork.GetYmenuGridPosition();
                ZoneID zoneID = UnionWork.GetYmenuZoneID();
                bool isZeroGrid = gridPos == Vector2Int.zero;
                int locatorIndex = -1;
                if (zoneID == ZoneID.C01 && isZeroGrid)
                {
                    zoneID = ZoneID.C01PC0102;
                    locatorIndex = 1;
                }

                PlayerWork.SetPlayerGrid(gridPos);
                PlayerWork.SetPlayerHeight(UnionWork.GetYmenuHeight());
                PlayerWork.SetPlayerRotation(0.0f);
                PlayerWork.SetTransitionZone(zoneID, locatorIndex);
                string label = "ev_connect_union_back_ymenu";
                if (NetworkManager.NetworkParam.networkType == IlcaNetSessionNetworkType.Internet)
                    label = "ev_connect_global_back_ymenu";

                EvDataManager.Instanse.JumpLabel(label, null);
            }
            else
            {
                if (returnZoneID == ZoneID.C01)
                {
                    returnZoneID = ZoneID.C01PC0102;
                    this.locatorIndex = 1;
                }

                PlayerWork.SetTransitionZone(returnZoneID, 1);
            }

            myPlayer.isMenuOpen = false;
            EvDataManager.Instanse.SetWork((int)EvWork.WORK_INDEX.UNION_TEMP0, 1);
        }
    }
