        if (isError)
        {
            AudioManager.Instance.SetBgmEvent(AK.EVENTS.BA_END, false);
            isError = false;
            battleMatchingManager.ReturnBattleError();
            NetworkError();
            return;
        }

        battleMatchingManager.ReturnBattle();
    }
