	private void LeaveOtherPlayer(int index) {
        if (_OpcManager != null)
            _OpcManager.RemoveCharacter(index, true);

        if (stateController != null && stateController.systemController.GetTargetStationIndex() == index)
        {
            OpcState.OnlineState state = myPlayer.opcState._curretOnlineState;
            switch (state)
            {
                case OpcState.OnlineState.RECRUITMENT_GREETINGS:
                case OpcState.OnlineState.COMMUNICATE:
                case OpcState.OnlineState.NOW_GREETINGS:
                    BattleRuleCancel();
                    stateController.SwitchCancelEnd();
                    UnionWork.SetIsTalk(false);
                    stateController.systemController.SetTargetStationIndex(-1, -1, true);
                    return;
                case OpcState.OnlineState.NONE:
                    nowTalkReserveState = OpcState.OnlineState.NONE;
                    PlayerWork.isPlayerInputActive = true;
                    UnionWork.SetIsTalk(false);
                    stateController.systemController.SetTargetStationIndex(-1, -1, true);
                    break;
                default:
                    if (stateController.GetTransitionController() == null)
                        break;

                    if (state == OpcState.OnlineState.NOW_BALL_DECORATION)
                    {
                        stateController.systemController.SetTargetStationIndex(-1, -1, true);
                        stateController.GetTransitionController().balldecoMatchingManager.LeaveOther();
                        return;
                    }

                    if (state == OpcState.OnlineState.NOW_RECORD)
                    {
                        stateController.systemController.SetTargetStationIndex(-1, -1, true);
                        stateController.GetTransitionController().recodeMatchingManager.LeaveOther();
                        return;
                    }

                    break;
            }

            if (battleMatchingManager != null && !battleMatchingManager.IsStateBattle)
            {
                battleMatchingManager.LeaveOther(index);
                return;
            }
        }

        if (tradeManager != null)
            tradeManager.CheckTragetNetworkError(index);
    }
