	private void NetworkError() {
        PlayerWork.isPlayerInputActive = false;
        player.PlayIdle();
        if (!isError)
            MsgWindowManager.ClearMsgWindowCallbackFunc();

        OpcState.OnlineState state = myPlayer != null ? myPlayer.GetOpcOnlineState() : OpcState.OnlineState.NONE;
        if (stateController != null)
        {
            stateController.InitPlayerState();
            stateController.CloseContextWindow();
            if (stateController.unionBattleRuleWindow != null)
                stateController.unionBattleRuleWindow.Hide();
        }

        if (pointCollision != null)
            pointCollision.CloseMessage();

        BattleRuleSelectWindow battleRuleSelectWindow = UIManager.Instance.GetExistWindow<BattleRuleSelectWindow>();
        if (battleRuleSelectWindow != null)
        {
            battleRuleSelectWindow.Close();
            MsgWindowManager.CloseMsg();
        }

        if (battleMatchingManager != null)
        {
            if (battleMatchingManager.IsStateBattle || !isActiveAndEnabled)
            {
                isError = true;
                return;
            }

            if (!battleMatchingManager.IsStateNone)
            {
                canLeave = false;
                battleMatchingManager.OnError();
            }
        }

        if (isError)
            return;

        isError = true;
        if (isLeaving)
            return;

        Action<ErrorAppletResult> onClosedAct = OpenSystemErrorMessage;
        if (state == OpcState.OnlineState.NOW_TRADE && tradeManager != null)
        {
            tradeManager.isError = true;
            switch (tradeManager.currentState)
            {
                case UnionTradeManager.TradeFlowState.NONE:
                    BoxWindow boxWindow = UIManager.Instance.GetExistWindow<BoxWindow>();
                    if (boxWindow != null)
                    {
                        boxWindow.Close(null, UIWindow.WINDOWID_FIELD);
                    }
                    else if (UIManager.Instance.GetExistWindow<PokemonStatusWindow>() != null)
                    {
                        // Shipped: the dialog is opened here AND again by the common tail below (@019e69a0 then @019e66d0).
                        tradeManager.currentState = UnionTradeManager.TradeFlowState.SELECT_WINDOW;
                        onClosedAct = tradeManager.TradeError;
                        canLeave = true;
                        OpenErrorDialog(ErrorCodeID.ErrorDisconnectionSession, onClosedAct);
                    }

                    break;
                case UnionTradeManager.TradeFlowState.SELECT_WINDOW:
                    UnionWork.SetBoxError(true);
                    BoxWindow.CloseOverUIWindows();
                    onClosedAct = tradeManager.TradeError;
                    canLeave = true;
                    OpenErrorDialog(ErrorCodeID.ErrorDisconnectionSession, onClosedAct);
                    return;
                case UnionTradeManager.TradeFlowState.SECURIY_TRADE:
                    onClosedAct = tradeManager.TradeError;
                    canLeave = true;
                    ErrorCodeID errorId = ErrorCodeID.ErrorDisconnectionSession;
                    TradeSecurityController securityController = tradeManager.securityController;
                    if (securityController != null && securityController.tradeStateModel != null && securityController.tradeStateModel.IsShowFatalError())
                    {
                        tradeManager.OnFatalError();
                        errorId = ErrorCodeID.FatalError;
                    }

                    OpenErrorDialog(errorId, onClosedAct);
                    return;
                case UnionTradeManager.TradeFlowState.PLAY_DEMO:
                    UnionWork.SetBoxState(UnionWork.BoxState.ERROR_OTHER);
                    return;
                default:
                    return;
            }
        }
        else
        {
            switch (state)
            {
                case OpcState.OnlineState.NONE:
                case OpcState.OnlineState.RECRUITMENT_BATTLE:
                case OpcState.OnlineState.RECRUITMENT_TRADE:
                case OpcState.OnlineState.RECRUITMENT_RECORD:
                case OpcState.OnlineState.RECRUITMENT_GREETINGS:
                case OpcState.OnlineState.RECRUITMENT_BALL_DECORATION:
                case OpcState.OnlineState.COMMUNICATE:
                case OpcState.OnlineState.NOW_BATTLE_UNION:
                case OpcState.OnlineState.NOW_TRADE:
                    break;
                case OpcState.OnlineState.NOW_RECORD:
                    OpenErrorDialog(ErrorCodeID.ErrorDisconnectionSession, onClosedAct);
                    if (stateController == null || stateController.GetTransitionController() == null)
                        return;

                    stateController.GetTransitionController().recodeMatchingManager.LeaveMine();
                    return;
                case OpcState.OnlineState.NOW_GREETINGS:
                    if (stateController != null && stateController.GetTransitionController() != null)
                        stateController.GetTransitionController().CreateUI = null;

                    OpenErrorDialog(ErrorCodeID.ErrorDisconnectionSession, onClosedAct);
                    CloseTargetTranerCard();
                    return;
                case OpcState.OnlineState.NOW_BALL_DECORATION:
                    OpenErrorDialog(ErrorCodeID.ErrorDisconnectionSession, onClosedAct);
                    if (stateController == null || stateController.GetTransitionController() == null)
                        return;

                    stateController.GetTransitionController().balldecoMatchingManager.LeaveMine();
                    return;
                default:
                    return;
            }
        }

        OpenErrorDialog(ErrorCodeID.ErrorDisconnectionSession, onClosedAct);
        if (stateController == null || stateController.GetTransitionController() == null)
            return;

        stateController.GetTransitionController().recodeMatchingManager.ForceClose();
        stateController.GetTransitionController().balldecoMatchingManager.ForceClose();
        stateController.GetTransitionController().CreateUI = null;
    }
	private void TradeErrorDialog() {
        OpenErrorDialog(ErrorCodeID.ErrorDisconnectionSession, OpenSystemErrorMessage);
    }
	private void OpenErrorDialog(global::Dpr.NetworkUtils.ErrorCodeID errorId, global::System.Action<global::Dpr.NetworkUtils.ErrorAppletResult> onClosedAct) {
        if (unionFrontController != null)
        {
            unionFrontController.TalkEnd();
            unionFrontController.Clear();
        }

        PlayerWork.isPlayerInputActive = false;
        if (NetworkManager.IsShowApplicationErrorDialog())
            return;

        NetworkManager.ShowApplicationErrorDialog(errorId, onClosedAct);
    }
	private void OpenSystemErrorMessage(global::Dpr.NetworkUtils.ErrorAppletResult errorAppletResult) {
        if (stateController.systemController == null)
            return;

        if (unionFrontController != null)
        {
            unionFrontController.TalkEnd();
            unionFrontController.Clear();
        }

        PlayerWork.isPlayerInputActive = false;
        UnionSystemController systemController = stateController.systemController;
        systemController.SetNetworkErrorMessage();
        UnionMsgSystemWindow unionMsgSystemWindow = systemController.unionMsgSystemWindow;
        unionMsgSystemWindow.OpenMsgWindow(0, UnionTextData.SpeakerID.SYSTEM);
        unionMsgSystemWindow.GetNowMessage().inputCloseEnabled = true;
        unionMsgSystemWindow.SetOnCloseCallBack(SetupLeave);
    }
