        return UnionWork.GetCommunicationState() != UnionWork.CommunicationState.NONE;
    }
	private void LeaveCommunicationPlayer(int stationIndex) {
        if (stateController == null || stateController.systemController == null || _OpcManager == null)
            return;

        UnionMsgSystemWindow unionMsgSystemWindow = stateController.systemController.unionMsgSystemWindow;
        if (unionMsgSystemWindow == null)
            return;

        if (stateController.unionBattleRuleWindow != null)
            stateController.unionBattleRuleWindow.Hide();

        PlayerWork.isPlayerInputActive = false;
        unionMsgSystemWindow.SetMessage(UnionTextData.UNION_MENU_NET_COMMUNICATION_MESSAGE_FILE_NAME, UnionTextData.UNION_SYSTEM_COMMUNICATE);
        unionMsgSystemWindow.OpenMsgWindow(0, UnionTextData.SpeakerID.SYSTEM);
        MsgWindowParam msgWindowParam = unionMsgSystemWindow.GetNowMessage();
        msgWindowParam.inputCloseEnabled = true;
        msgWindowParam.onFinishedCloseWindow = InputEnebled;

        void InputEnebled()
        {
            PlayerWork.isPlayerInputActive = true;
        }
    }
