	protected override void OnReceiveData(global::Dpr.NetworkUtils.INetData netData) {
        SetNetData(netData);
        _OpcManager.SetNetData(netData);
    }
	protected override void SetNetData(global::Dpr.NetworkUtils.INetData netData) {
        if (NetDataTalkCancelEndData.DataID == netData.GetDataID || NetDataBattleRuleCancelData.DataID == netData.GetDataID)
        {
            // Shipped: the battle-matching test appears twice in the condition (@019e7eb4 / @019e7ef4).
            if ((battleMatchingManager != null && !battleMatchingManager.IsStateNone) ||
                (tradeManager != null && tradeManager.currentState != UnionTradeManager.TradeFlowState.NONE) ||
                (stateController != null && stateController.GetTransitionController() != null && stateController.GetTransitionController().recodeMatchingManager.isOpen) ||
                (battleMatchingManager != null && !battleMatchingManager.IsStateNone))
            {
                int targetStationIndex = UnionWork.nowTargetStationIndex;
                if (tradeManager != null && tradeManager.currentState != UnionTradeManager.TradeFlowState.NONE)
                    targetStationIndex = tradeManager.tradeTargetIndex;

                if (netData.FromStationIndex == targetStationIndex)
                    CancelUIState(netData);
            }
        }

        if (NetJoinData.DataID == netData.GetDataID)
        {
            _OpcManager.CreateCharacter((NetJoinData)netData);
            return;
        }

        if (NetRequestData.DataID == netData.GetDataID)
        {
            NetRequestData requestData = (NetRequestData)netData;
            byte requestDataID = requestData.data.RequestDataID;
            int fromStationIndex = requestData.FromStationIndex;
            if (requestDataID == NetJoinData.DataID)
                SendJoinData(fromStationIndex);

            if (requestDataID == NetCharacterStateData.DataID)
                SendOpcStateData(fromStationIndex);

            if (requestDataID == NetDataStandbyWaitListData.DataID)
                SendStandbyPlayerData(fromStationIndex);

            if (requestDataID == NetTradePokeData.DataID)
                SendPokeData(fromStationIndex);

            if (requestDataID == NetDataBattleTypeData.DataID)
                SendBattleRuleData(fromStationIndex);

            if (requestDataID == NetDataIsMatchWaitData.DataID)
                SendIsMatchWait(fromStationIndex);

            return;
        }

        if (NetDataTalkReserveData.DataID == netData.GetDataID)
        {
            NetDataTalkReserveResultData talkReserveResultData = new NetDataTalkReserveResultData();
            talkReserveResultData.data.IsCanTalk = (byte)(UnionWork.GetIsTalk() ? 1 : 0);
            // Shipped: a FromStationIndex read whose result is never used (@019e83e4).
            int unusedFromStationIndex = netData.FromStationIndex;
            if (stateController.currentModel == null)
            {
                talkReserveResultData.data.IsCanTalk = 1;
                SendOpcStateData(netData.FromStationIndex);
            }

            talkReserveResultData.data.IsRecruitment = 1;
            talkReserveResultData.data.emoticonStateType = (byte)myPlayer.opcState._curretOnlineState;
            talkReserveResultData.SendReliableData(netData.FromStationIndex);
            if (UnionWork.GetIsTalk())
                return;

            if (talkReserveResultData.data.IsCanTalk != 0)
                return;

            UnionWork.SetIsTalk(true);
            return;
        }

        if (NetDataTalkReserveResultData.DataID == netData.GetDataID)
        {
            NetDataTalkReserveResultData resultData = (NetDataTalkReserveResultData)netData;
            bool isCanStartTalk = resultData.data.IsCanTalk == 0;
            int fromStationIndex = resultData.FromStationIndex;
            byte isRecruitment = resultData.data.IsRecruitment;
            byte emoticonStateType = resultData.data.emoticonStateType;
            if (isCancelStock)
            {
                isCanStartTalk = false;
                isCancelStock = false;
            }

            UnionOpcController controller = (UnionOpcController)_OpcManager.GetOpc(fromStationIndex);
            if (emoticonStateType == (byte)nowTalkReserveState)
            {
                nowTalkReserveState = OpcState.OnlineState.NONE;
                if (isCanStartTalk)
                {
                    StartTalk(controller, isRecruitment == 0, true, OpcState.OnlineState.NONE);
                    return;
                }
            }
            else
            {
                NetDataTalkCancelEndData talkCancelEndData = new NetDataTalkCancelEndData();
                talkCancelEndData.data = new CancelEndData();
                talkCancelEndData.SendReliableData(netData.FromStationIndex);
                nowTalkReserveState = OpcState.OnlineState.NONE;
            }

            if (controller.GetOpcOnlineState() == OpcState.OnlineState.RECRUITMENT_BATTLE ||
                controller.GetOpcOnlineState() == OpcState.OnlineState.RECRUITMENT_TRADE ||
                controller.GetOpcOnlineState() == OpcState.OnlineState.RECRUITMENT_RECORD ||
                controller.GetOpcOnlineState() == OpcState.OnlineState.RECRUITMENT_GREETINGS ||
                controller.GetOpcOnlineState() == OpcState.OnlineState.RECRUITMENT_BALL_DECORATION)
            {
                PlayerWork.isPlayerInputActive = false;
                StartTalk(controller, isRecruitment == 0, false, OpcState.OnlineState.COMMUNICATE);
            }
            else
            {
                PlayerWork.isPlayerInputActive = true;
            }

            UnionWork.SetIsTalk(false);
            stateController.systemController.SetTargetStationIndex(-1, -1, true);
            return;
        }

        if (NetDataCurrentFlowCancelData.DataID == netData.GetDataID)
        {
            NetDataCurrentFlowCancelData currentFlowCancelData = (NetDataCurrentFlowCancelData)netData;
            if (tradeManager != null)
                tradeManager.ReciveCancelData(currentFlowCancelData);

            return;
        }

        if (NetTradePokeData.DataID == netData.GetDataID)
        {
            NetTradePokeData tradePokeData = (NetTradePokeData)netData;
            if (tradeManager != null)
                RecivePokeData(tradePokeData);

            return;
        }

        if (NetDataTradeReadyOkData.DataID == netData.GetDataID)
        {
            NetDataTradeReadyOkData tradeReadyOkData = (NetDataTradeReadyOkData)netData;
            if (tradeManager != null)
                tradeManager.ReciveTradeReadyOkData(tradeReadyOkData);

            return;
        }

        if (NetDataStandbyWaitListData.DataID == netData.GetDataID)
        {
            NetDataStandbyWaitListData standbyWaitListData = (NetDataStandbyWaitListData)netData;
            if (stateController != null)
                stateController.ReciveMatchWaitListData(standbyWaitListData);

            return;
        }

        if (NetDataStandbyWaitData.DataID == netData.GetDataID)
        {
            NetDataStandbyWaitData standbyWaitData = (NetDataStandbyWaitData)netData;
            if (stateController != null)
                stateController.ReciveMatchWaitData(standbyWaitData);

            return;
        }

        if (NetDataIsMatchWaitData.DataID == netData.GetDataID)
        {
            NetDataIsMatchWaitData isMatchWaitData = (NetDataIsMatchWaitData)netData;
            if (_OpcManager == null)
                return;

            List<OpcController> opcControllers = _OpcManager.GetOpcControllerList();
            if (opcControllers == null)
                return;

            int fromStationIndex = isMatchWaitData.FromStationIndex;
            bool isMatchWait = isMatchWaitData.data.isMatchWait == 1;
            for (int i = 0; i < opcControllers.Count; i++)
            {
                if (opcControllers[i] == null)
                    continue;

                UnionOpcController opcController = (UnionOpcController)opcControllers[i];
                if (opcController.stationIndex == fromStationIndex)
                    opcController.SetIsMultiMatchWait(isMatchWait);
            }

            return;
        }

        if (NetDataTradeTranerData.DataID == netData.GetDataID)
        {
            NetDataTradeTranerData tradeTranerData = (NetDataTradeTranerData)netData;
            IlcaNetGamer gamer = NetworkManager.GetGamerData(tradeTranerData.FromStationIndex);
            uint tranerId = tradeTranerData.data.tranerId;
            byte cassetVersion = tradeTranerData.data.cassetVersion;
            byte langId = tradeTranerData.data.langId;
            string tranerName = tradeTranerData.data.tranerName;
            // Shipped: the tagged name is computed and thrown away; the raw name is passed on (@019e906c / @019e907c).
            MessageHelper.SurroundFontTag(tranerName, (uint)gamer.nameStringLanguage);
            if (tradeManager != null)
                tradeManager.SetTargetTranerParam(tranerId, tranerName, cassetVersion, (MessageEnumData.MsgLangId)langId);

            return;
        }

        if (NetDataReturnSelectData.DataID == netData.GetDataID)
        {
            NetDataReturnSelectData returnSelectData = (NetDataReturnSelectData)netData;
            if (tradeManager != null)
                tradeManager.ReciveReturnSelectPoke(returnSelectData);

            return;
        }

        if (NetDataTradePokeCheckOkData.DataID == netData.GetDataID)
        {
            NetDataTradePokeCheckOkData tradePokeCheckOkData = (NetDataTradePokeCheckOkData)netData;
            if (tradeManager != null)
                tradeManager.ReciveTradePokeCheckOk(tradePokeCheckOkData);

            return;
        }

        if (netData.GetDataID == NetDataBattleMatchingJoin.DataID ||
            netData.GetDataID == NetDataBattleMatchingLeave.DataID ||
            netData.GetDataID == NetDataBattleMatchingReady.DataID ||
            netData.GetDataID == NetDataBattleMatchingState.DataID ||
            netData.GetDataID == NetDataBattleMatchingSelectTeam.DataID ||
            netData.GetDataID == NetDataBattleMatchingDecideTeam.DataID ||
            netData.GetDataID == NetDataBattleMatchingSelectRuleMember.DataID ||
            netData.GetDataID == NetDataBattleMatchingDecideRuleMember.DataID ||
            netData.GetDataID == NetDataBattleMatchingRule.DataID ||
            netData.GetDataID == NetDataBattleMatchingSelectPokemon.DataID ||
            netData.GetDataID == NetDataBattleMatchingCancelPokemon.DataID ||
            netData.GetDataID == NetDataBattleMatchingResume.DataID ||
            netData.GetDataID == NetDataBattleMatchingCountDown.DataID)
        {
            if (battleMatchingManager != null)
                battleMatchingManager.ReceiveData(netData);

            return;
        }

        if (stateController.currentModel == null)
        {
            if (NetPosData.DataID == netData.GetDataID)
                return;

            if (NetDataTransitionAfterData.DataID == netData.GetDataID)
                return;

            if (NetCharacterStateData.DataID == netData.GetDataID)
                return;

            if (NetDataTalkCancelEndData.DataID == netData.GetDataID)
                return;

            NetDataTalkCancelEndData talkCancelEndData = new NetDataTalkCancelEndData();
            talkCancelEndData.data = new CancelEndData();
            talkCancelEndData.SendReliableData(netData.FromStationIndex);
            SendOpcStateData(netData.FromStationIndex);
            return;
        }

        if (NetDataTalkCancelEndData.DataID == netData.GetDataID)
        {
            NetDataTalkCancelEndData talkCancelEndData = (NetDataTalkCancelEndData)netData;
            int fromStationIndex = talkCancelEndData.FromStationIndex;
            if (!UnionWork.GetIsTalk())
                isCancelStock = true;

            if (stateController.systemController.GetTargetStationIndex() != fromStationIndex)
                return;

            stateController.SwitchCancelEnd();
            UnionWork.SetIsTalk(false);
            stateController.systemController.SetTargetStationIndex(-1, -1, true);
            return;
        }

        if (NetDataTalkData.DataID == netData.GetDataID)
        {
            NetDataTalkData talkData = (NetDataTalkData)netData;
            stateController.SwitchSpokenStateMine(talkData.FromStationIndex, talkData.data.talkState);
            UnionWork.SetIsTalk(true);
            return;
        }

        if (NetDataTransitionData.DataID == netData.GetDataID)
        {
            NetDataTransitionData transitionData = (NetDataTransitionData)netData;
            bool isRecruitment = transitionData.data.isRecruitment == 1;
            int fromStationIndex = transitionData.FromStationIndex;
            byte transitionType = transitionData.data.transitionType;
            // The binary leaves w3 (fromStationIndex) unset: SwitchTransitionMessage never reads it (@019e9cf4–019e9d18).
            stateController.SwitchTransitionMessage(transitionType, _OpcManager.GetSexId(fromStationIndex), fromStationIndex, isRecruitment);
            return;
        }

        if (NetDataBattleTypeData.DataID == netData.GetDataID)
        {
            NetDataBattleTypeData battleTypeData = (NetDataBattleTypeData)netData;
            stateController.SwitchBatttleStateTalk(battleTypeData.FromStationIndex, (BattleModeID)battleTypeData.data.type);
            return;
        }

        if (NetDataBattleRuleCancelData.DataID == netData.GetDataID)
        {
            BattleRuleCancel();
            stateController.SwitchCancelEnd();
            UnionWork.SetIsTalk(false);
            stateController.systemController.SetTargetStationIndex(-1, -1, true);
            return;
        }

        if (NetDataSelectData.DataID == netData.GetDataID)
        {
            NetDataSelectData selectData = (NetDataSelectData)netData;
            BattleRecruitmentStateModel recruitmentModel = stateController.GetBattleRecruimentModel();
            int fromStationIndex = selectData.FromStationIndex;
            recruitmentModel.ChangeBattleRecruitmentState(BattleRecruitmentStateModel.BattleRecruitmentState.BATTLE_RULE_SELECT_WAIT);
            stateController.GetBattleRecruimentModel().SetCancelModel(new CancelModel { reason = CancelModel.CancelReason.SelectCancel, fromStationIndex = fromStationIndex });
            recruitmentModel.CloseWindow();
            if (stateController.GetBattleRecruimentModel().unionMsgBattleWindow == null)
                return;

            recruitmentModel.unionMsgBattleWindow.SetTargetDataMessage(fromStationIndex, 1, 1);
            recruitmentModel.unionMsgBattleWindow.OpenMsgWindow(3, UnionTextData.SpeakerID.SYSTEM);
            return;
        }

        if (NetDataTranerCardData.DataID == netData.GetDataID)
        {
            NetDataTranerCardData tranerCardData = (NetDataTranerCardData)netData;
            targetTrainerData = tranerCardData.data;
            int stationIndex = tranerCardData.FromStationIndex;
            stateController.GetTransitionController().CreateUI = () =>
            {
                OpenTargetTranerCard(targetTrainerData, stationIndex);
                return true;
            };
            return;
        }

        if (NetDataAttachSealNetData.DataID == netData.GetDataID)
        {
            if (stateController != null && stateController.GetTransitionController() != null)
                stateController.GetTransitionController().balldecoMatchingManager.ReceiveData(netData);

            return;
        }

        if (netData.GetDataID == NetDataRecodeData.DataID)
        {
            if (stateController != null && stateController.GetTransitionController() != null)
                stateController.GetTransitionController().recodeMatchingManager.ReceiveData(netData);
        }
    }
	protected override global::System.Collections.IEnumerator LoadAsset() {
        AssetManager.AppendAssetBundleRequest(UNION_MASTER_PATH, true, null, null);
        AssetManager.AppendAssetBundleRequest(UNION_BATTLE_DISPLAY_PATH, true, null, null);
        yield return AssetManager.DispatchRequests((eventType, name, asset) =>
        {
            if (eventType == RequestEventType.Complete)
            {
                AssetManager.UnloadAssetBundle(name);
                return;
            }

            if (eventType != RequestEventType.Activated)
                return;

            if (name == CHARACTER_DATATABLE_PATH)
                _characterTable = ((UnionCharacterTable)asset).Sheet1;

            if (name == NPC_COLOR_DATATABLE)
                _npcColorTable = ((UnionNpcColorTable)asset).Sheet1;

            if (name == BATTLE_RULE_WINDOW_PATH)
                battleRuleDisplayUiObj = (GameObject)asset;
        });
    }
