	private void SendPosData() {
        PosData posData = new PosData();
        if (!UnionWork.CheckNetworkState() || !NetworkManager.Instance.IsJoinOtherPlayer())
        {
            posDataIndex = 0;
            for (int i = 0; i < posDataList.Length; i++)
                posDataList[i] = new PosData();

            return;
        }

        FieldPlayerEntity fieldPlayer = player;
        posData = new PosData();
        posData.pos = new Vector2(fieldPlayer.worldPosition.x, fieldPlayer.worldPosition.z);
        posData.rotY = (short)fieldPlayer.transform.eulerAngles.y;
        if (posDataIndex >= POSITION_DATA_MAX_SIZE)
        {
            posDataIndex = 0;
            return;
        }

        posDataList[posDataIndex] = posData;
        posDataIndex++;
        if (Time.frameCount % POSITION_DATA_MAX_SIZE != 0)
            return;

        short rotY = (short)fieldPlayer.transform.eulerAngles.y;
        Vector2 nowPos = new Vector2(fieldPlayer.worldPosition.x, fieldPlayer.worldPosition.z);
        bool isSend = false;
        for (int i = 0; i < posDataList.Length; i++)
        {
            if (posDataList[i].pos == Vector2.zero)
            {
                isSend = false;
                break;
            }

            if (!Utils.IsInDistance(posDataList[i].pos, nowPos, 0.1f) || posDataList[i].rotY != rotY)
                isSend = true;
        }

        if (isSend)
        {
            NetPosData netPosData = new NetPosData();
            netPosData.data.posDatasList = posDataList;
            netPosData.SendUnReliableDataToAll();
        }

        posDataIndex = 0;
        for (int i = 0; i < posDataList.Length; i++)
            posDataList[i] = new PosData();
    }
