	private void SendStandbyPlayerData(int stationIndex) {
        if (stateController == null)
            return;

        List<UnionMatchWaitData> waitDataList = stateController.unionMatchWaitDataList;
        if (waitDataList == null)
            return;

        NetDataStandbyWaitListData standbyWaitListData = new NetDataStandbyWaitListData();
        standbyWaitListData.data.standbyDataList = new StandbyData[5];
        for (int i = 0; i < waitDataList.Count; i++)
        {
            if (waitDataList[i] == null)
                continue;

            UnionMatchWaitData waitData = waitDataList[i];
            // Shipped: hostIndex is never written (the packed word @019ea730–019ea748 is 1 | myIndex << 16 | langId << 24).
            standbyWaitListData.data.standbyDataList[i] = new StandbyData { isAddPlayer = 1, myIndex = (byte)waitData.myStationIndex, langId = (byte)waitData.langId };
        }

        standbyWaitListData.SendReliableData(stationIndex);
    }
