        NetTradePokeData tradePokeData = new NetTradePokeData();
        if (tradeManager == null)
            return;

        PokemonParam pokemonParam = tradeManager.GetSelectMyPokemonParam();
        if (pokemonParam == null)
            return;

        if (tradeManager.tradeSelectModel == null || !tradeManager.tradeSelectModel.GetIsSendPokeParam())
