	private void RecivePokeData(global::Dpr.NetworkUtils.NetTradePokeData netTradePokeData) {
        UnionTradeManager.TradeFlowState currentState = tradeManager.currentState;
        byte[] pokeData = netTradePokeData.data.pokeData;
        PokemonParam pokemonParam = new PokemonParam();
        pokemonParam.Deserialize_Core(pokeData);
        switch (currentState)
        {
            case UnionTradeManager.TradeFlowState.SELECT_WINDOW:
            case UnionTradeManager.TradeFlowState.PLAY_DEMO:
                tradeManager.RecivePokeData(pokemonParam);
                break;
            case UnionTradeManager.TradeFlowState.SECURIY_TRADE:
                tradeManager.SetSecurityTradeParam();
                break;
        }
    }
	private void StartTalk(global::UnionOpcController controller, bool IsRecruitment, bool IsTargetCanTalk, global::OpcState.OnlineState onlineState = (global::OpcState.OnlineState)(0)) {
        if (controller == null)
            return;

        OpcState.OnlineState controllerState = controller.GetOpcOnlineState();
        if (onlineState == OpcState.OnlineState.NONE)
            onlineState = controllerState;

        if (onlineState == OpcState.OnlineState.NONE)
        {
            UnionWork.SetIsTalk(false);
            PlayerWork.isPlayerInputActive = true;
            return;
        }

        if (!unionFrontController.isTalkEnd)
            return;

        player.PlayIdle();
        stateController.SwitchTalkStateMine(onlineState, controller);
        if (!IsTargetCanTalk)
            return;

        stateController.SettingCurrentState(controller.stationIndex, onlineState, IsRecruitment);
    }
