        return EvDataManager.Instanse.GetWork(EvWork.WORK_INDEX._UNION_VIEW_CHAR_NO);
    }
	private global::UnityEngine.Vector3 GetStartPos() {
        if (matchingParam.netType == IlcaNetSessionNetworkType.Local)
            return UnionWork.startPos;

        return UnionWork.startPosGlobal;
    }
	private void CancelUIState(global::Dpr.NetworkUtils.INetData talkCancel) {
        if (battleMatchingManager != null && !battleMatchingManager.IsStateNone)
        {
            battleMatchingManager.ReceiveData(talkCancel);
            return;
        }

        if (tradeManager != null && tradeManager.currentState != UnionTradeManager.TradeFlowState.NONE)
        {
            // Shipped: the cancel packet is not passed on (x1 = xzr @019ea46c).
            tradeManager.ReciveCancelData(null);
            return;
        }

        if (stateController == null || stateController.GetTransitionController() == null)
            return;

        if (stateController.GetTransitionController().recodeMatchingManager.isOpen)
        {
            stateController.GetTransitionController().recodeMatchingManager.ReceiveData(talkCancel);
            return;
        }

        if (stateController.GetTransitionController().balldecoMatchingManager.isOpen)
            stateController.GetTransitionController().balldecoMatchingManager.ReceiveData(talkCancel);
    }
	private void OpenTargetTranerCard(global::Dpr.NetworkUtils.TranerData tranerData, int stationIndex) {
        UICard card = UIManager.Instance.CreateUIWindow<UICard>(UIWindowID.CARD);
        TranerCardData cardData = tranerData.cardData;
        IlcaNetGamer gamer = NetworkManager.GetGamerData(stationIndex);
        string gamerName = gamer != null ? gamer.gamerName : null;
        PlayerNameData playerNameData = new PlayerNameData();
        UICard.Param param = new UICard.Param();
        playerNameData.genderid = tranerData.genderid;
        playerNameData.lanugageId = (MessageEnumData.MsgLangId)tranerData.langId;
        playerNameData.nickName = gamerName;
        OpcController opc = stateController.unionOpcManager.GetOpc(stationIndex);
        if (opc != null)
            playerNameData.nickName = Utils.CheckNGTrainerName(ref playerNameData.nickName, playerNameData.lanugageId, opc._CharaData.cassetVersion);

        param.PlayerFashion = tranerData.fashionId;
        param.PlayerBodyType = tranerData.bodyType;
        param.PlayerSex = tranerData.genderid != 1;
        param.PlayerId = cardData.tranerId;
        param.CardRank = tranerData.tranerRank;
        param.PlayerNameData = playerNameData;
        param.Money = (int)cardData.money;
        param.PlayTimeMinute = cardData.playTimeMinute;
        param.IsShowBadgeCase = false;
        param.ZukanSeeCount = (int)cardData.zukanCount;
        param.IsGetZukan = cardData.isZukanGet == 1;
        param.PlayTimeHour = cardData.playTimeHour;
        param.StartTime = cardData.startTime;
        param.ClearTime = cardData.clearTime;
        param.ContestStyleRank = cardData.styleRank;
        param.ContestBeatifulRank = cardData.beatifulRank;
        param.ContestCuteRank = cardData.cuteRank;
        param.ContestCleverRank = cardData.cleverRank;
        param.ContestStrongRank = cardData.strongRank;
        param.TowerRenshouSingle = cardData.renshouSingle;
        param.TowerRenshouDouble = cardData.renshouDouble;
        param.TowerRenshouMasterSingle = cardData.renshouSingleMaster;
        param.TowerRenshouMasterDouble = cardData.renshouDoubleMaster;
        param.PoffinCookingCount = cardData.cookingCount;
        param.DigFossilPlayCount = cardData.digFossilPlayCount;
        param.HaveStatueKindNum = cardData.getHaveStatueKindNum;
        card.Open(param, UIWindow.WINDOWID_FIELD);
        card.onClosed = window =>
        {
            PlayerWork.isPlayerInputActive = true;
            if (stateController != null)
                stateController.InitPlayerState();

            UnionWork.SetIsTalk(false);
        };

        if (stateController != null && stateController.systemController != null)
            stateController.systemController.SetTargetStationIndex(-1, -1, true);
    }
	private void CloseTargetTranerCard() {
        UICard card = UIManager.Instance.GetExistWindow<UICard>();
        if (card != null && !card.IsClosing)
            card.Close(null, card.prevWindowId);
    }
